function validate([pieces, positions]) {
  if (!Array.isArray(pieces) || pieces.length < 1 || pieces.length > 4) return 'pieces needs 1 to 4 entries.';
  if (!Array.isArray(positions) || positions.length !== pieces.length) return 'positions needs one square per piece.';
  if (pieces.some(p => p !== 'rook' && p !== 'queen' && p !== 'bishop')) return 'Each piece is "rook", "queen" or "bishop".';
  if (pieces.filter(p => p === 'queen').length > 1) return 'There is at most one queen.';
  const seen = new Set();
  for (const square of positions) {
    if (!Array.isArray(square) || square.length !== 2) return 'Each position is [r, c].';
    const [r, c] = square;
    if (!Number.isInteger(r) || !Number.isInteger(c) || r < 1 || r > 8 || c < 1 || c > 8) return 'Rows and columns are between 1 and 8.';
    if (seen.has(r * 10 + c)) return 'Pieces start on different squares.';
    seen.add(r * 10 + c);
  }
  return null;
}

