function countCombinations(pieces, positions) {
  const straight = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const diagonal = [[1, 1], [1, -1], [-1, 1], [-1, -1]];
  const directions = new Map([
    ['rook', straight],
    ['bishop', diagonal],
    ['queen', [...straight, ...diagonal]],
  ]);
  const n = pieces.length;
  const taken = new Array(7 * 64).fill(false);

  function trace(row, col, dr, dc, steps) {
    const cells = [];
    for (let time = 1; time <= 7; time++) {
      const walked = Math.min(time, steps);
      const square = (row - 1 + dr * walked) * 8 + (col - 1 + dc * walked);
      cells.push((time - 1) * 64 + square);
    }
    return cells;
  }

  const moves = positions.map(([row, col], i) => {
    const list = [trace(row, col, 0, 0, 0)];
    for (const [dr, dc] of directions.get(pieces[i])) {
      for (let steps = 1; ; steps++) {
        const r = row + dr * steps;
        const c = col + dc * steps;
        if (r < 1 || r > 8 || c < 1 || c > 8) break;
        list.push(trace(row, col, dr, dc, steps));
      }
    }
    return list;
  });

  function place(i) {
    if (i === n) return 1;
    let count = 0;
    for (const cells of moves[i]) {
      if (cells.some(cell => taken[cell])) continue;
      for (const cell of cells) taken[cell] = true;
      count += place(i + 1);
      for (const cell of cells) taken[cell] = false;
    }
    return count;
  }

  return place(0);
}

