function countCombinations(pieces, positions) {
  const n = pieces.length;
  const targets = positions.map(([r, c], i) => {
    const list = [];
    for (let tr = 1; tr <= 8; tr++) for (let tc = 1; tc <= 8; tc++) {
      const line = tr === r || tc === c;
      const diag = Math.abs(tr - r) === Math.abs(tc - c);
      const ok = pieces[i] === 'rook' ? line : pieces[i] === 'bishop' ? diag : line || diag;
      if (ok) list.push([tr, tc]);
    }
    return list;
  });
  let total = 0;
  const pick = new Array(n);
  const simulate = () => {
    const rows = positions.map(p => p[0]);
    const cols = positions.map(p => p[1]);
    for (let sec = 0; sec < 8; sec++) {
      for (let i = 0; i < n; i++) {
        rows[i] += Math.sign(pick[i][0] - rows[i]);
        cols[i] += Math.sign(pick[i][1] - cols[i]);
      }
      for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) if (rows[i] === rows[j] && cols[i] === cols[j]) return false;
    }
    return true;
  };
  const go = (i) => {
    if (i === n) { if (simulate()) total++; return; }
    for (const t of targets[i]) { pick[i] = t; go(i + 1); }
  };
  go(0);
  return total;
}

