function generate(rand, size) {
  const n = size === 'large' ? 4 : 1 + Math.floor(rand() * 4);
  const kinds = ['rook', 'bishop', 'queen'];
  const pieces = [];
  let queens = 0;
  for (let i = 0; i < n; i++) {
    let kind = kinds[Math.floor(rand() * 3)];
    if (kind === 'queen' && queens > 0) kind = rand() < 0.5 ? 'rook' : 'bishop';
    if (kind === 'queen') queens++;
    pieces.push(kind);
  }
  // Small inputs often crowd the pieces together so their paths cross.
  const span = size === 'small' && rand() < 0.6 ? 3 : 8;
  const low = 1 + Math.floor(rand() * (9 - span));
  const used = new Set();
  const positions = [];
  while (positions.length < n) {
    const r = low + Math.floor(rand() * span);
    const c = low + Math.floor(rand() * span);
    if (used.has(r * 10 + c)) continue;
    used.add(r * 10 + c);
    positions.push([r, c]);
  }
  return [pieces, positions];
}
